    // CraftingOrder::WriteCreate
    public static void CraftingOrder(ForeverPacketWriter w, UfValues v, string p)
    {
        CraftingOrderData(w, v, p + ".Data");
        w.Bit(v.Has(p + ".RecraftItemInfo"));
        w.Bits((uint)(v.N(p + ".Enchantments")), 4);
        w.Bits((uint)(v.N(p + ".Gems")), 2);
        w.Flush();
        if (v.Has(p + ".RecraftItemInfo"))
        {
            w.I32((int)v.I(p + ".RecraftItemInfo"+".ItemID")).Bits(0, 7).Flush().Bit(false).Flush();
        }
        for (var i = 0; i < v.N(p + ".Enchantments"); i++)
        {
            throw new System.NotSupportedException("CraftingOrder enchantments");
        }
        for (var i = 0; i < v.N(p + ".Gems"); i++)
        {
            throw new System.NotSupportedException("CraftingOrder gems");
        }
        w.Flush();
    }

