    // CraftingOrderData::WriteCreate
    public static void CraftingOrderData(ForeverPacketWriter w, UfValues v, string p)
    {
        w.I32((int)v.I(p + ".Field_0"));
        w.U64((ulong)v.I(p + ".OrderID"));
        w.I32((int)v.I(p + ".SkillLineAbilityID"));
        w.I32((int)v.I(p + ".OrderState"));
        w.U8((byte)v.I(p + ".OrderType"));
        w.U8((byte)v.I(p + ".MinQuality"));
        w.I64(v.I(p + ".ExpirationTime"));
        w.I64(v.I(p + ".ClaimEndTime"));
        w.I64(v.I(p + ".TipAmount"));
        w.I64(v.I(p + ".ConsortiumCut"));
        w.U32((uint)v.I(p + ".Flags"));
        w.Guid(v.G(p + ".CrafterGUID"));
        w.Guid(v.G(p + ".PersonalCrafterGUID"));
        w.I32((int)v.I(p + ".NpcCraftingOrderSetID"));
        w.I32((int)v.I(p + ".NpcTreasureID"));
        w.U32((uint)v.N(p + ".Reagents"));
        for (var i = 0; i < v.N(p + ".Reagents"); i++)
        {
            CraftingOrderItem(w, v, p + ".Reagents[" + i + "]");
        }
        w.Bits((uint)(Encoding.UTF8.GetByteCount(v.S(p + ".CustomerNotes"))), 10);
        w.Bit(v.Has(p + ".Customer"));
        w.Bit(v.Has(p + ".NpcCustomer"));
        w.Bit(v.Has(p + ".OutputItem"));
        w.Bit(v.Has(p + ".OutputItemData"));
        w.Flush();
        w.Raw(Encoding.UTF8.GetBytes(v.S(p + ".CustomerNotes")));
        if (v.Has(p + ".Customer"))
        {
            CraftingOrderCustomer(w, v, p + ".Customer");
        }
        if (v.Has(p + ".NpcCustomer"))
        {
            CraftingOrderNpcCustomer(w, v, p + ".NpcCustomer");
        }
        if (v.Has(p + ".OutputItem"))
        {
            CraftingOrderItem(w, v, p + ".OutputItem");
        }
        if (v.Has(p + ".OutputItemData"))
        {
            w.I32((int)v.I(p + ".OutputItemData"+".ItemID")).Bits(0, 7).Flush().Bit(false).Flush();
        }
    }

